def comps(s):
 g=[list(map(int,l.split())) for l in s.strip().splitlines()]; R=len(g);C=len(g[0]); seen=set(); out=[]
 for r in range(R):
  for c in range(C):
   if g[r][c]==0 and (r,c) not in seen:
    st=[(r,c)];seen.add((r,c)); q=[]
    while st:
     x,y=st.pop();q.append((x,y))
     for a,b in ((x+1,y),(x-1,y),(x,y+1),(x,y-1)):
      if 0<=a<R and 0<=b<C and g[a][b]==0 and (a,b) not in seen:seen.add((a,b));st.append((a,b))
    out.append(q)
 return sorted(out,key=len,reverse=True)
